+// arrayValue transforms an attribute Value of ARRAY type into an slice of
+// OTLP AnyValue.
+func arrayValue(arr interface{}) []*commonpb.AnyValue {
+	var av []*commonpb.AnyValue
+	switch val := arr.(type) {
+	case []bool:
+		av = make([]*commonpb.AnyValue, len(val))
+		for i, v := range val {
